# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Timekeeping::LocalOwner reservation checkpoints" do
  # "Call the optional `checkpoint:` callable after each step."
  it "local prepare and commit call checkpoint after each step in order with names from STEPS" do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation
    company = create(:company)
    user = create(:user)
    project = create(:project, client: create(:client, company_id: company.id))
    entry = Timekeeping::LocalEntry.create!(
      company_id: company.id, user_id: user.id, project_id: project.id, work_date: Date.new(2026, 3, 2),
      duration: 60.0, bill_status: "unbilled"
    )
    actor = Timekeeping::LocalOwner::Actor.service(
      name: "invoice-boundary", company_id: company.id,
      operations: %w[reservations.prepare reservations.commit reservations.abort invoices.mark_billed agents.detach_entries]
    )
    operation_id = SecureRandom.uuid
    run = lambda do |operation, body|
      steps = []
      outcome = Timekeeping::LocalOwner.call(
        operation:, company_id: company.id, generation: generation.to_s, actor:,
        params: { "body" => body.merge("operation_id" => operation_id, "invoice_id" => 501, "generation" => generation) },
        checkpoint: ->(step) { steps << step.to_sym }
      )
      expect(outcome.status).to eq(200)
      steps
    end

    prepare_steps = run.call(:prepare, { "disposition" => "active", "entries" => [entry.id] })
    commit_steps = run.call(:commit, {})

    expect(prepare_steps + commit_steps).to all(satisfy { |step| Timekeeping::LocalOwner::STEPS.include?(step) })
    expected_prepare = %i[operation_key_locked generation_checked operation_checked rows_locked decision_made
                          reservations_written entry_written audit_written outbox_written]
    expect(prepare_steps & expected_prepare).to eq(expected_prepare)
    expected_commit = %i[operation_key_locked generation_checked rows_locked decision_made reservations_written receipt_written]
    expect(commit_steps & expected_commit).to eq(expected_commit)
    # Committing a provisional reservation flips no locked flag, so no entry change is written.
    expect(commit_steps).not_to include(:entry_written)
  end
end
